package cc.aaro.cosign

import cc.aaro.cosign.core.Frost
import cc.aaro.cosign.core.Secp
import cc.aaro.cosign.core.hexToBytes
import cc.aaro.cosign.core.toHex
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import java.math.BigInteger

/** The phone's FROST against vectors generated by the servers' (server/test/vectors.ts). */
class FrostVectorsTest {
    private val v = JSONObject(javaClass.classLoader!!.getResource("frost.json")!!.readText())
    private val groupX = v.getString("groupX")

    @Test fun lagrange() {
        val a = v.getJSONArray("lagrange")
        for (k in 0 until a.length()) {
            val o = a.getJSONObject(k)
            val p = o.getJSONArray("p").let { arr -> (0 until arr.length()).map { arr.getInt(it) } }
            assertEquals(o.getString("expect"), Frost.bytes32(Frost.lagrange(o.getInt("i"), p)).toHex())
        }
    }

    @Test fun sharePublicPoints() {
        val a = v.getJSONArray("shares")
        for (k in 0 until a.length()) {
            val o = a.getJSONObject(k)
            assertEquals(o.getString("pub"), Frost.sharePub(o.getString("secret")))
        }
    }

    @Test fun partialSignaturesMatchTheServer() {
        val phoneSecret = v.getJSONArray("shares").getJSONObject(2).getString("secret")
        val a = v.getJSONArray("sign")
        var flipped = 0
        for (k in 0 until a.length()) {
            val o = a.getJSONObject(k)
            val cs = o.getJSONArray("commits")
            val commits = (0 until cs.length()).map { cs.getJSONObject(it) }.map { Frost.Commit(it.getInt("idx"), it.getString("D"), it.getString("E")) }
            val p = o.getJSONObject("phone")
            val z = Frost.partialSign(
                groupX, o.getString("msg"), commits, p.getInt("idx"), phoneSecret,
                Frost.Nonces(BigInteger(p.getString("d"), 16), BigInteger(p.getString("e"), 16)),
            )
            assertEquals("vector $k", o.getString("expectZ"), z)
            // And the aggregate the server made from it is a plain BIP-340 signature.
            assertTrue(Secp.verify(o.getString("sig").hexToBytes(), o.getString("msg").hexToBytes(), groupX.hexToBytes()))
            if (o.getBoolean("flip")) flipped++
        }
        assertTrue("both parities of R are covered", flipped in 1 until a.length())
    }

    @Test fun ecdhPartialsMatchTheServer() {
        val phoneSecret = v.getJSONArray("shares").getJSONObject(2).getString("secret")
        val a = v.getJSONArray("ecdh")
        for (k in 0 until a.length()) {
            val o = a.getJSONObject(k)
            val p = o.getJSONArray("participants").let { arr -> (0 until arr.length()).map { arr.getInt(it) } }
            assertEquals(o.getString("expect"), Frost.ecdhPartial(o.getInt("idx"), phoneSecret, p, o.getString("peerX")))
        }
    }
}
